[dependencies]
# LSP client, anchored diagnostics, and request helpers for the window.
kate-lsp = { workspace = true }

/// The items below are pub(crate).
/// One row of the diagnostics pane.
#[derive(Clone, Debug, PartialEq, Eq)]
struct DiagnosticRow {
    pub line: u32,
    pub col: u32,
    pub severity: kate_lsp::diagnostics::Severity,
    pub message: String,
}

/// The items below are pub(crate).
/// One underline on one line, in columns.
#[derive(Clone, Debug, PartialEq, Eq)]
struct Underline {
    pub line: u32,
    pub start_col: u32,
    pub end_col: u32,
    pub severity: kate_lsp::diagnostics::Severity,
}

/// The items below are pub(crate).
/// Rows sorted by line then column. A stale diagnostic is dropped.
fn diagnostic_rows(buf: &kate_text::TextBuffer, diagnostics: &[kate_lsp::diagnostics::Diagnostic]) -> Vec<DiagnosticRow>
/// Underlines for lines `first..last`. A diagnostic over several lines gives one underline per line; an empty span gets one column.
fn underlines_for_lines(buf: &kate_text::TextBuffer, diagnostics: &[kate_lsp::diagnostics::Diagnostic], first: u32, last: u32) -> Vec<Underline>
